import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { packageRoot } from './paths.js'
import { resolveFile } from './resolve.js'
import { ensureDir, writeText } from './fsx.js'
import { parse } from './yaml.js'

/**
 * The SDD skeleton: a task folder is generated by code from the pipeline template and
 * checked by `lint`, so the structure never depends on an agent remembering it.
 *
 * The template (`lib/pipeline/spec-template.md`) stays the single source of truth: the
 * fenced block under each file's heading is what gets written, with the placeholders
 * filled in.
 */

const TEMPLATE = 'lib/pipeline/spec-template.md'
export const SLUG = /^[a-z0-9]+(-[a-z0-9]+)*$/
export const CLASSES = ['fix', 'feature', 'big-feature']

const PROPOSAL_KEYS = ['status', 'project', 'task', 'class', 'created']
const SPEC_KEYS = ['spec_id', 'status', 'last_updated', 'freshness_check']
const SPEC_STATUS = ['draft', 'in_progress', 'blocked', 'done', 'obsolete']
const PROPOSAL_STATUS = ['in-progress', 'done', 'paused']
const FRESHNESS = ['ok', 'stale', 'pending']

/** The first fenced block under a `## \`file\`` heading of the template. */
function templateBlock(text, file) {
  const heading = text.indexOf(`## \`${file}\``)
  if (heading === -1) throw new Error(`Template has no section for ${file}`)
  const open = text.indexOf('```', heading)
  const bodyStart = text.indexOf('\n', open) + 1
  const close = text.indexOf('```', bodyStart)
  return text.slice(bodyStart, close).replace(/\r\n/g, '\n')
}

function today() {
  return new Date().toISOString().slice(0, 10)
}

function headCommit(cwd) {
  try {
    return execFileSync('git', ['rev-parse', '--short', 'HEAD'], { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim()
  } catch {
    return 'none'
  }
}

function titleFrom(slug) {
  const words = slug.replace(/-/g, ' ')
  return words.charAt(0).toUpperCase() + words.slice(1)
}

function fill(block, values) {
  return block
    .replace(/^linked_release:.*\n/m, '')
    .replace(/<project-name>/g, values.project)
    .replace(/<task-slug>/g, values.slug)
    .replace(/<short task name>/g, values.title)
    .replace(/<sha>/g, values.commit)
    .replace(/YYYY-MM-DD/g, values.date)
    .replace(/^class: [\w-]+ /m, `class: ${values.klass} `)
}

/** Writes the task folder; throws if it already exists. Returns the files written. */
export function createTask(cwd, sddRoot, { repo, slug, klass = 'feature', project }) {
  if (!SLUG.test(repo)) throw new Error(`Repo "${repo}" must be lowercase, hyphen-separated.`)
  if (!SLUG.test(slug)) throw new Error(`Task slug "${slug}" must be lowercase, hyphen-separated (rules/naming.md).`)
  if (!CLASSES.includes(klass)) throw new Error(`Class must be one of: ${CLASSES.join(', ')}.`)

  const dir = path.join(sddRoot, 'specs', repo, slug)
  if (fs.existsSync(dir)) throw new Error(`${path.relative(cwd, dir)} already exists.`)

  const source = resolveFile(cwd, TEMPLATE) ?? path.join(packageRoot, TEMPLATE)
  const text = fs.readFileSync(source, 'utf8')
  const values = {
    project: project ?? path.basename(cwd),
    slug,
    title: titleFrom(slug),
    commit: headCommit(cwd),
    date: today(),
    klass,
  }

  ensureDir(dir)
  const written = []
  for (const file of ['proposal.md', 'spec.md', 'design.md']) {
    writeText(path.join(dir, file), fill(templateBlock(text, file), values))
    written.push(file)
  }
  // A new task has no steps yet: keep the template's header and numbering note, drop its sample steps.
  const tasksBlock = fill(templateBlock(text, 'tasks.yaml'), values)
  writeText(path.join(dir, 'tasks.yaml'), tasksBlock.slice(0, tasksBlock.indexOf('tasks:')) + 'tasks: []\n')
  written.push('tasks.yaml')
  return { dir, written }
}

function frontmatter(file) {
  const text = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n')
  if (!text.startsWith('---\n')) return null
  const end = text.indexOf('\n---', 4)
  if (end === -1) return null
  try {
    return parse(text.slice(4, end)) ?? {}
  } catch {
    return null
  }
}

/** Problems found in one task folder, as plain strings. Missing files are not problems. */
export function checkTask(dir, label) {
  const problems = []
  const slug = path.basename(dir)

  const checkFile = (name, keys, extra) => {
    const file = path.join(dir, name)
    if (!fs.existsSync(file)) return
    const meta = frontmatter(file)
    if (!meta) return problems.push(`${label}/${name} — missing or unreadable frontmatter`)
    for (const key of keys) if (meta[key] == null || meta[key] === '') problems.push(`${label}/${name} — frontmatter lacks "${key}"`)
    extra(meta, name)
  }

  checkFile('proposal.md', PROPOSAL_KEYS, (meta, name) => {
    if (meta.task != null && String(meta.task) !== slug) problems.push(`${label}/${name} — task "${meta.task}" does not match the folder name`)
    if (meta.status != null && !PROPOSAL_STATUS.includes(String(meta.status))) problems.push(`${label}/${name} — status "${meta.status}" is not one of ${PROPOSAL_STATUS.join(', ')}`)
    if (meta.class != null && !CLASSES.includes(String(meta.class))) problems.push(`${label}/${name} — class "${meta.class}" is not one of ${CLASSES.join(', ')}`)
  })
  checkFile('spec.md', SPEC_KEYS, (meta, name) => {
    if (meta.spec_id != null && String(meta.spec_id) !== slug) problems.push(`${label}/${name} — spec_id "${meta.spec_id}" does not match the folder name`)
    if (meta.status != null && !SPEC_STATUS.includes(String(meta.status))) problems.push(`${label}/${name} — status "${meta.status}" is not one of ${SPEC_STATUS.join(', ')}`)
    if (meta.freshness_check != null && !FRESHNESS.includes(String(meta.freshness_check))) problems.push(`${label}/${name} — freshness_check "${meta.freshness_check}" is not one of ${FRESHNESS.join(', ')}`)
  })

  const tasks = path.join(dir, 'tasks.yaml')
  if (fs.existsSync(tasks)) {
    try {
      const doc = parse(fs.readFileSync(tasks, 'utf8')) ?? {}
      if (doc.version == null) problems.push(`${label}/tasks.yaml — lacks "version"`)
      if (doc.tasks != null && !Array.isArray(doc.tasks)) problems.push(`${label}/tasks.yaml — "tasks" must be a list`)
    } catch {
      problems.push(`${label}/tasks.yaml — does not parse`)
    }
  }
  return problems
}

/** Every task folder under `<root>/specs/<repo>/<task>/`. */
export function taskDirs(root) {
  const specs = path.join(root, 'specs')
  if (!fs.existsSync(specs)) return []
  const out = []
  for (const repo of fs.readdirSync(specs, { withFileTypes: true })) {
    if (!repo.isDirectory()) continue
    for (const task of fs.readdirSync(path.join(specs, repo.name), { withFileTypes: true })) {
      if (task.isDirectory()) out.push({ dir: path.join(specs, repo.name, task.name), label: `specs/${repo.name}/${task.name}` })
    }
  }
  return out
}
